import React, { useState, useRef, DragEvent } from 'react';
import ColorThief from 'color-thief-browser';

type ToneStyle = "감성" | "정보" | "캐주얼" | "세일";

interface CopyTemplate {
  template: string;
  tone: ToneStyle;
}

interface PhraseBank {
  [mood: string]: string[];
}

interface FallbackMap {
  [mood: string]: string;
}

interface BannerCopyGeneratorFinalProps {
  onHome: () => void;
}

const copyTemplates: CopyTemplate[] = [
  { template: "{situation}엔 {mood} {noun}이 제격", tone: "정보" },
  { template: "{mood} 무드로 {situation}을 준비해봐", tone: "감성" },
  { template: "{noun} 하나로 완성하는 {mood} 무드", tone: "정보" },
  { template: "{mood} 무드를 입다", tone: "감성" },
  { template: "{mood} 분위기를 더해주는 {noun}", tone: "감성" },
  { template: "툭 걸쳐도 {mood}하게", tone: "캐주얼" },
  { template: "오늘의 기분, {mood}", tone: "감성" },
  { template: "{situation}엔 {mood}하게", tone: "정보" },
  { template: "감도 높은 {mood}, 감각적인 무드", tone: "감성" },
  { template: "자연스럽게 {mood}한 하루", tone: "감성" },
  { template: "취향을 담은 {mood} 포인트", tone: "감성" },
  { template: "살짝 힘 뺀 {mood} 무드", tone: "감성" },
  { template: "단 하나의 톤으로 정제된 멋", tone: "감성" },
  { template: "무심한 듯 정리된 선", tone: "정보" },
  { template: "멋있는데, 티 안 나는 거 알지?", tone: "캐주얼" }
];

const fallbackMood: FallbackMap = {
  "에너지 넘치는": "따뜻한",
  "감각적인": "차분한",
  "우아한": "차분한",
  "화려한": "따뜻한",
  "밝은": "따뜻한",
  "따스한": "따뜻한",
  "고요한": "차분한"
};

const phraseBank: PhraseBank = {
  "따뜻한": [
    "따뜻하게 감싸주는 느낌",
    "따뜻한 감성으로 물들다",
    "오늘은 따뜻한 무드로",
    "햇살 아래 어울리는 따스함",
    "포근함 가득 안아줄게"
  ],
  "차분한": [
    "말수 적은 멋, 차분함 그대로",
    "톤 다운된 감성으로",
    "조용히 빛나는 스타일",
    "무심한 듯 차분하게",
    "시선 머무는 차분함"
  ]
};

const nouns = ["컬러감", "실루엣", "포인트", "핏", "디테일"];
const situations = ["출근", "데이트", "주말", "여행", "소풍"];
const moods = ["따뜻한", "차분한"];

function getRandomItem<T>(arr: T[]): T {
  return arr[Math.floor(Math.random() * arr.length)];
}

// 대표 색상 → 태그 매핑 예시 (간단 버전)
const colorToTags: Record<string, {
  style: string[];
  season: string[];
  situation: string[];
}> = {
  pastel: { style: ['미니멀', '러블리'], season: ['봄', '여름'], situation: ['데일리', '데이트'] },
  black: { style: ['모던', '오피스룩'], season: ['겨울', '가을'], situation: ['오피스'] },
  blue: { style: ['캐주얼', '스트릿'], season: ['여름'], situation: ['캠퍼스'] },
  brown: { style: ['빈티지', '클래식'], season: ['가을', '겨울'], situation: ['데일리', '캠퍼스'] },
  white: { style: ['미니멀', '모던'], season: ['봄', '여름'], situation: ['데일리', '홈웨어'] },
  red: { style: ['러블리', '캐주얼'], season: ['봄', '여름'], situation: ['데이트', '파티룩'] },
  green: { style: ['내추럴', '빈티지'], season: ['봄', '여름'], situation: ['소풍', '캠퍼스'] },
  purple: { style: ['클래식', '모던'], season: ['가을', '겨울'], situation: ['오피스'] },
  yellow: { style: ['캐주얼', '러블리'], season: ['봄', '여름'], situation: ['데일리', '소풍'] },
};

const styleTags = ['미니멀', '모던', '스트릿', '빈티지', '캐주얼', '러블리', '클래식', '오피스룩', '내추럴'];
const seasonTags = ['봄', '여름', '가을', '겨울'];
const situationTags = ['데일리', '데이트', '파티룩', '오피스', '캠퍼스', '홈웨어', '소풍'];

function rgbToSimpleColor([r, g, b]: number[]): string {
  if (r > 200 && g < 100 && b < 100) return "red";
  if (r > 200 && g > 120 && b < 80) return "pastel";
  if (r > 200 && g > 200 && b < 100) return "yellow";
  if (g > 150 && r < 120 && b < 120) return "green";
  if (b > 180 && r < 120 && g < 180) return "blue";
  if (r > 150 && b > 150 && g < 120) return "purple";
  if (r > 100 && g > 70 && b < 50) return "brown";
  if (r < 60 && g < 60 && b < 60) return "black";
  if (r > 200 && g > 200 && b > 200) return "white";
  if (r > 150 && g > 150 && b > 150) return "white";
  return "white";
}

const BannerCopyGenerator_Final: React.FC<BannerCopyGeneratorFinalProps> = ({ onHome }) => {
  const [input, setInput] = useState('');
  const [results, setResults] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [image, setImage] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [selectedTags, setSelectedTags] = useState<{ style: string[]; season: string[]; situation: string[] }>({ style: [], season: [], situation: [] });
  const [dragActive, setDragActive] = useState(false);
  const imgRef = useRef<HTMLImageElement>(null);

  // 이미지 업로드 및 대표색 추출
  const handleDrag = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleUploadFile(e.dataTransfer.files[0]);
    }
  };

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) handleUploadFile(file);
  };

  const handleUploadFile = (file: File) => {
    setImage(file);
    setPreviewUrl(URL.createObjectURL(file));
    setResults([]);
    setSelectedTags({ style: [], season: [], situation: [] });
  };

  const handleImageLoad = async () => {
    if (!imgRef.current) return;
    const colorThief = new ColorThief();
    try {
      const palette: number[][] = await colorThief.getPalette(imgRef.current, 8);
      const rgb = palette[0] || [200, 200, 200];
      const colorKey = rgbToSimpleColor(rgb);
      const tags = colorToTags[colorKey] || { style: [], season: [], situation: [] };
      setSelectedTags({
        style: tags.style,
        season: tags.season,
        situation: tags.situation
      });
    } catch (e) {
      setSelectedTags({ style: [], season: [], situation: [] });
    }
  };

  // 태그 수동 선택
  const handleTagChange = (type: keyof typeof selectedTags, value: string) => {
    setSelectedTags(prev => {
      const arr = prev[type];
      return {
        ...prev,
        [type]: arr.includes(value) ? arr.filter(v => v !== value) : [...arr, value]
      };
    });
  };

  // 문구 생성
  const handleGenerate = () => {
    setLoading(true);
    setTimeout(() => {
      // 입력값이 있으면 mood/situation/noun에 반영, 없으면 태그 기반
      const mood = input.trim() ? input.trim() : (selectedTags.style[0] || getRandomItem(moods));
      const fallback = fallbackMood[mood] || mood;
      const noun = getRandomItem(nouns);
      const situation = selectedTags.situation[0] || getRandomItem(situations);
      const applicableTemplates = copyTemplates.filter(t => phraseBank[fallback]);
      const template = getRandomItem(applicableTemplates);
      const phrase = template.template
        .replace("{mood}", fallback)
        .replace("{noun}", noun)
        .replace("{situation}", situation);
      setResults([phrase, ...results].slice(0, 3));
      setLoading(false);
    }, 400);
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    alert('클립보드에 복사되었습니다!');
  };

  const resetTags = () => {
    setSelectedTags({ style: [], season: [], situation: [] });
  };

  return (
    <div className="card" style={{ maxWidth: 847, margin: "32px auto", background: '#fff', boxShadow: '0 2px 12px #e0e7ef', borderRadius: 16, padding: '28px' }}>
      <div className="flex" style={{ alignItems: 'center', marginBottom: '20px' }}>
        <button onClick={onHome} style={{ background: '#22c55e', color: 'white', border: 'none', borderRadius: '6px', padding: '8px 12px', display: 'flex', alignItems: 'center', gap: '4px', cursor: 'pointer', fontSize: '14px', fontWeight: '600' }}>
          <span role="img" aria-label="home">🏠</span> 홈
        </button>
        <h2 style={{ marginLeft: '16px', fontSize: '1.5rem', color: '#1e293b', fontWeight: 700 }}>
          🖼️ 배너 이미지 문구 추천 (최종 버전)
        </h2>
      </div>

      {/* 텍스트 입력 영역 */}
      <div style={{ marginBottom: '20px' }}>
        <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
          ✍️ 문구 생성하기
        </h3>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <input
            type="text"
            value={input}
            onChange={e => setInput(e.target.value)}
            placeholder="원하는 무드/키워드를 입력해보세요 (예: 따뜻한, 차분한 등)"
            style={{ 
              flex: 1,
              padding: '10px', 
              fontSize: '1rem', 
              borderRadius: 6, 
              border: '1px solid #d1d5db',
              outline: 'none'
            }}
          />
          <button 
            onClick={handleGenerate} 
            disabled={loading} 
            style={{ 
              padding: '10px 18px', 
              fontSize: '1rem', 
              background: '#3b82f6', 
              color: 'white', 
              border: 'none', 
              borderRadius: 6, 
              fontWeight: 600,
              cursor: loading ? 'not-allowed' : 'pointer',
              opacity: loading ? 0.6 : 1
            }}
          >
            {loading ? '생성 중...' : '문구 생성'}
          </button>
        </div>
      </div>

      {/* 업로드 영역 */}
      <div className="mb-20">
        <h3 style={{ fontSize: '1.2rem', marginBottom: '15px', color: '#1e293b' }}>
          🖼️ 이미지 문구 추출하기
        </h3>
        <div
          className="card"
          style={{ textAlign: 'center', padding: '30px', border: dragActive ? '2px dashed #3b82f6' : undefined, background: dragActive ? '#f0f6ff' : undefined }}
          onDrop={handleDrop}
          onDragOver={handleDrag}
          onDragLeave={handleDrag}
        >
          <input
            id="banner-img-upload"
            type="file"
            accept="image/*"
            style={{ display: 'none' }}
            onChange={handleUpload}
          />
          {!previewUrl ? (
            <div>
              <div style={{ fontSize: '3rem', marginBottom: '20px' }}>📁</div>
              <h4 style={{ marginBottom: '15px', color: '#1e293b' }}>이미지 업로드</h4>
              <p style={{ color: '#64748b', marginBottom: '20px' }}>
                이미지를 클릭하거나, 이 영역에 드래그해서 업로드할 수 있어요
              </p>
              <button 
                className="btn" 
                onClick={() => document.getElementById('banner-img-upload')?.click()}
                style={{ 
                  fontSize: '1.1rem', 
                  padding: '12px 24px',
                  background: '#3b82f6',
                  color: 'white'
                }}
              >
                이미지 선택하기
              </button>
            </div>
          ) : (
            <div>
              <img
                ref={imgRef}
                src={previewUrl}
                alt="업로드 이미지"
                style={{
                  maxWidth: 220,
                  maxHeight: 220,
                  borderRadius: '16px',
                  marginBottom: '12px',
                  boxShadow: '0 2px 12px #e5e7eb',
                  objectFit: 'cover',
                  display: 'block',
                  marginLeft: 'auto',
                  marginRight: 'auto'
                }}
                crossOrigin="anonymous"
                onLoad={handleImageLoad}
              />
              <button 
                className="btn" 
                onClick={() => { setImage(null); setPreviewUrl(null); setSelectedTags({ style: [], season: [], situation: [] }); }}
                style={{ marginRight: '10px' }}
              >
                이미지 다시 선택하기
              </button>
            </div>
          )}
        </div>
      </div>

      {/* 태그 선택 영역 */}
      {image && (
        <div style={{ marginTop: '24px' }}>
          <hr style={{border: 'none', borderTop: '1px solid #e5e7eb', margin: '0 0 24px 0'}} />
          <div style={{ textAlign: 'center', marginBottom: '16px' }}>
            <div style={{ color: '#64748b', fontSize: 13, marginTop: 2 }}>
              추출된 태그: {[...selectedTags.style, ...selectedTags.season, ...selectedTags.situation].join(', ')}
            </div>
          </div>
          <div style={{
            display: 'grid',
            gridTemplateColumns: '1fr 1fr',
            gap: 32,
            marginBottom: 16
          }}>
            {/* 1컬럼: 스타일 + 계절 */}
            <div>
              <div style={{ fontWeight: 700, color: '#2563eb', marginBottom: 6, fontSize: 16 }}>스타일</div>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, marginBottom: 10 }}>
                {styleTags.map(t => (
                  <label key={t} style={{ fontWeight: 500, color: '#334155', minWidth: 48, fontSize: 13, marginRight: 8, marginBottom: 2, whiteSpace: 'nowrap' }}>
                    <input type="checkbox" checked={selectedTags.style.includes(t)} onChange={() => handleTagChange('style', t)} /> {t}
                  </label>
                ))}
              </div>
              <div style={{ fontWeight: 700, color: '#2563eb', marginBottom: 4, fontSize: 15, marginTop: 10 }}>계절</div>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, marginBottom: 10 }}>
                {seasonTags.map(t => (
                  <label key={t} style={{ fontWeight: 500, color: '#334155', minWidth: 48, fontSize: 13, marginRight: 8, marginBottom: 2, whiteSpace: 'nowrap' }}>
                    <input type="checkbox" checked={selectedTags.season.includes(t)} onChange={() => handleTagChange('season', t)} /> {t}
                  </label>
                ))}
              </div>
            </div>
            {/* 2컬럼: 상황 */}
            <div>
              <div style={{ fontWeight: 700, color: '#15803d', marginBottom: 6, fontSize: 16 }}>상황</div>
              <div style={{ fontWeight: 700, color: '#16a34a', marginBottom: 4, fontSize: 15 }}>TPO</div>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 10 }}>
                {situationTags.map(t => (
                  <label key={t} style={{ fontWeight: 500, color: '#334155', minWidth: 60, fontSize: 13 }}>
                    <input type="checkbox" checked={selectedTags.situation.includes(t)} onChange={() => handleTagChange('situation', t)} /> {t}
                  </label>
                ))}
              </div>
            </div>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginTop: 8, marginBottom: 8 }}>
            <button onClick={resetTags} style={{ background: '#f1f5f9', color: '#334155', border: 'none', borderRadius: 6, padding: '6px 14px', fontWeight: 500, cursor: 'pointer', fontSize: 13 }}>초기화</button>
          </div>
          <button
            onClick={handleGenerate}
            disabled={loading || !image}
            className="btn"
            style={{
              background: "#3b82f6",
              color: "white",
              fontWeight: 600,
              borderRadius: 8,
              padding: "10px 0",
              fontSize: 15,
              border: "none",
              cursor: loading || !image ? "not-allowed" : "pointer",
              marginBottom: 10,
              width: '100%'
            }}
          >
            {loading ? "문구 생성 중..." : "새로운 문구 추천받기"}
          </button>
          {loading && (
            <div style={{ textAlign: "center", margin: "10px 0", color: "#64748b", fontSize: 13 }}>
              문구 생성 중입니다... 잠시만 기다려주세요.
            </div>
          )}
        </div>
      )}

      {/* 결과 표시 */}
      {results.length > 0 && (
        <div style={{ background: "#f8fafc", borderRadius: 8, padding: 10, marginTop: 6, maxHeight: 220, overflowY: 'auto' }}>
          {results.map((line, i) => (
            <div key={i} className="card" style={{ background: '#fff', borderRadius: 8, boxShadow: '0 1px 4px #e0e7ef', marginBottom: 8, padding: '10px 12px', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}>
              <div style={{ whiteSpace: "pre-line", fontSize: 14, color: '#1e293b', fontWeight: 500 }}>{line}</div>
              <button className="btn btn-secondary" style={{ fontSize: '0.9rem', padding: '5px 10px', borderRadius: 6, background: '#e0e7ef', color: '#2563eb', fontWeight: 600, border: 'none', cursor: 'pointer' }} onClick={() => copyToClipboard(line)}>
                복사
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default BannerCopyGenerator_Final;
